	"metric.vo2max.label": "VO₂ max",
	"metric.ageGrade.label": "Age grade",
	"metric.ageGrade.definition": "Age grade — your time scored against the best on record for your age and sex. Around 60% is a strong local runner; 80% is national class.",
	"metric.vert.label": "Vert",
	"metric.vert.definition": "Vert — the total height you climbed, added up across every uphill.",
	"metric.trimp.label": "TRIMP",
	"metric.trimp.definition": "TRIMP (training impulse) — a score for how hard a run was, from how long it lasted and how high your heart rate went.",
	"metric.riegel.label": "Riegel formula",
	"metric.riegel.definition": "Riegel formula — a standard way to predict your time at one race distance from a time you ran at another.",
	"metric.vdot.label": "VDOT",
	"metric.vdot.definition": "VDOT — a running fitness score from coach Jack Daniels' formula, worked out from a recent race time. Higher is fitter, and your training paces are set from it.",
	"metric.distanceBanked.definition": "Distance banked — how much of this plan's total distance you've already run.",
	"metric.planPhases.label": "Training phases",
	"metric.planPhases.definition": "Training phases — Base builds easy running, Build adds harder sessions, Peak is the toughest block, Taper eases off so you arrive fresh, and Race week is the last easy days before the race.",
	"metric.e1rm.definition": "1RM (one-rep max) — the heaviest weight you could lift for a single rep. An estimated 1RM is worked out from the weight and reps of a set you did, so you never have to test it.",
	"metric.e1rm.inline": "estimated one-rep max (1RM)",
	"metric.rpe.definition": "RPE (rate of perceived exertion) — how hard a set felt, from 1 to 10. A 10 means you couldn't have done one more rep.",
	"metric.kom.label": "KOM/QOM",
	"metric.kom.definition": "KOM/QOM (King / Queen of the Mountain) — the crown for the fastest time on a segment, one for men and one for women.",
	"dash.ctlTooltip": "Fitness (CTL) — your rolling 42-day training load. Builds slowly; this is your endurance base.",
	"dash.ctlLabel": "CTL (fitness)",
