	"settingsIntegrations.title": "Integrations",
	"settingsIntegrations.tagline": "Bring your runs in from the apps and watches you already use — or drop in a bulk export file if you'd rather not connect an account.",
	"settingsIntegrations.loading": "Loading integrations…",
	"settingsIntegrations.emptyTitle": "No integrations connected",
	"settingsIntegrations.emptyText": "Connect an account below to keep your runs flowing in automatically. Or use the bulk-import cards if you'd rather drop in a one-off export.",
	"settingsIntegrations.availableHeading": "Available integrations",
	"settingsIntegrations.infoAbout": "About {name}",
	"settingsIntegrations.strandedNote": "This connection is still linked to your account but can't sync here. Disconnect it if you no longer need it.",
	"settingsIntegrations.stravaInfo": "Strava is a popular app for recording and sharing runs. Connecting it copies your Strava activities across — the last 90 days first, then each new one as it appears. You'll sign in to Strava and approve access, and you can disconnect at any time.",
	"settingsIntegrations.parkrunInfo": "parkrun is a free, weekly, timed 5k held in parks around the world. Connecting records that you take part; to pull your results in, enter the athlete number from your parkrun barcode (the one starting with A) under Settings, Account, then choose Pull parkrun results.",
	"settingsIntegrations.garminInfo": "Garmin Connect is where a Garmin watch stores your activities. An automatic account link isn't available yet — Garmin has to approve it. Until then, \"Bulk import from a Garmin export\" further down this page brings in the same runs from a file, with no account link needed.",
	"settingsIntegrations.healthkitInfo": "Apple HealthKit is the health store on an iPhone, where workouts from every app end up. It only works on the device itself, so there is nothing for a web browser to connect to — it syncs inside the iPhone app instead.",
	"settingsIntegrations.stravaBulkInfo": "Connecting Strava only pulls recent activity. If you have used Strava for years, a bulk export brings in everything. Ask Strava for your archive under Settings, My Account, Download or Delete Your Account; wait for the email, which can take a few hours; then drop the zip file here. Runs you already have are skipped.",
	"settingsIntegrations.garminBulkInfo": "This brings your Garmin history in from a file instead of an account link. Either export a single activity from Garmin Connect with \"Export Original\", or request your full data from Garmin Account Management and drop the zip here when the email arrives. Runs you already have are skipped.",
	"settingsIntegrations.stravaDescription": "Sync activities automatically from your Strava account",
	"settingsIntegrations.parkrunDescription": "Import your complete parkrun history",
	"settingsIntegrations.parkrunRegionNote": "parkrun operates in a limited set of countries and may not have events near you — you can still connect if you have a parkrun athlete ID.",
	"settingsIntegrations.garminDescription": "Bulk-import .fit files (single activity or full Account Data export). Live OAuth needs Garmin developer-program approval.",
	"settingsIntegrations.healthkitDescription": "Will sync on-device once the iOS app ships (coming soon).",
	"settingsIntegrations.lastSynced": "Last synced {date}",
