	"compare.heroHeading": "Everything Strava Pro has — free.",
	"compare.tagline": "Strava paywalls the features that make running data actually useful: heart-rate zones, pace heatmaps, best-effort detection, training-load curves, live tracking. We ship all of it for free, plus a couple of things even Strava Pro doesn’t do (readiness score, tiered {term} crowns).",
