	// Guided-run library (S-1) — script copy mirrors the mobile
	// twin's ARB catalogue (guidedRunLibrary). Timing lives in code.
	"guidedRuns.easy30.title": "30-Minute Easy Run",
	"guidedRuns.easy30.subtitle": "Coach voice · 30 min · easy effort",
	"guidedRuns.easy30.description": "A relaxed, conversational-pace run for a recovery day or just clearing your head. Coach checks in every five minutes with a gentle nudge.",
	"guidedRuns.easy30.cue0": "Let’s go. Start easy — this is your recovery pace.",
	"guidedRuns.easy30.cue1": "Five minutes in. Drop your shoulders. Keep it conversational.",
	"guidedRuns.easy30.cue2": "Ten minutes. Cadence check — quick feet, light landing.",
	"guidedRuns.easy30.cue3": "Halfway. You should still be able to talk through this.",
	"guidedRuns.easy30.cue4": "Twenty minutes. Notice your breathing — slow nasal in, mouth out.",
	"guidedRuns.easy30.cue5": "Five to go. Stay relaxed. Don’t pick it up.",
	"guidedRuns.easy30.cue6": "One minute left. Easy finish.",
	"guidedRuns.easy30.cue7": "Done. Walk it out for a minute. Nice job.",
	"guidedRuns.tempo25.title": "25-Minute Tempo Builder",
	"guidedRuns.tempo25.subtitle": "Coach voice · 25 min · 5-15-5",
	"guidedRuns.tempo25.description": "Five-minute easy warm-up, fifteen minutes at tempo (comfortably hard), five-minute cool-down. The bread-and-butter weekly tempo session.",
	"guidedRuns.tempo25.cue0": "Warm-up time. Five minutes easy — wake up the legs.",
	"guidedRuns.tempo25.cue1": "One minute left in the warm-up. Pick up the cadence.",
	"guidedRuns.tempo25.cue2": "Lift it to tempo. Comfortably hard. Like a 10K race effort.",
	"guidedRuns.tempo25.cue3": "Five minutes in tempo. Strong but controlled. Keep the rhythm.",
	"guidedRuns.tempo25.cue4": "Ten minutes of tempo done. Hold the pace.",
	"guidedRuns.tempo25.cue5": "Two minutes left at tempo. Stay smooth.",
	"guidedRuns.tempo25.cue6": "Ease off. Five minutes easy to cool down.",
	"guidedRuns.tempo25.cue7": "Two to go. Bring the heart rate back down.",
