	"deleteAccount.documentTitle": "Delete your account — Threkir",
	"deleteAccount.metaDescription": "How to delete your Threkir account and all associated data, with or without the app installed.",
	"deleteAccount.h1": "Delete your account",
	"deleteAccount.lead": "This page explains how to permanently delete your Threkir account and the data associated with it. You do not need the app installed to request deletion.",
	"deleteAccount.lastUpdated": "Last updated: {date}",
	"deleteAccount.s1Heading": "1. Delete your account yourself",
	"deleteAccount.s1Intro": "Deletion is self-service and takes effect immediately:",
	"deleteAccount.s1WebLabel": "On the web",
	"deleteAccount.s1WebPrefix": ": sign in, open ",
	"deleteAccount.s1WebLink": "Settings → Account",
	"deleteAccount.s1WebMiddle": ", and choose ",
	"deleteAccount.s1WebAction": "Delete account",
	"deleteAccount.s1WebSuffix": ". You will be asked to type your account email to confirm. (Opening that link while signed out takes you through sign-in and back.)",
	"deleteAccount.s1MobileLabel": "In the mobile app",
	"deleteAccount.s1MobileBody": ": Settings → Account → Delete account, with the same typed confirmation.",
	"deleteAccount.s1PermanentPrefix": "Deletion is ",
	"deleteAccount.s1PermanentEmphasis": "permanent and cannot be undone",
	"deleteAccount.s1PermanentSuffix": ". When it completes we send a one-time confirmation email to the account address as a receipt.",
	"deleteAccount.s2Heading": "2. If you can't sign in",
	"deleteAccount.s2Prefix": "Email ",
	"deleteAccount.s2Suffix": " from the email address on the account and ask us to delete it. We verify the request by matching (or confirming a link sent to) that address, then run the same deletion described below and confirm when it is done — within one month at the latest, usually much sooner.",
	"deleteAccount.s3Heading": "3. What is deleted",
	"deleteAccount.s3Intro": "Deleting the account removes your data across our database and file storage, including:",
	"deleteAccount.s3Profile": "your profile (name, avatar, settings, follower relationships);",
	"deleteAccount.s3Runs": "runs and their GPS tracks, routes, race results, and personal records;",
	"deleteAccount.s3Files": "photos and every other file you uploaded, including generated data exports;",
	"deleteAccount.s3Gym": "gym workouts, routines, session plans, food logs, and body metrics;",
	"deleteAccount.s3Training": "training plans, coach chat history, and AI Coach consent records;",
	"deleteAccount.s3Social": "posts, comments, kudos, the direct messages you sent, and club memberships;",
	"deleteAccount.s3Notifications": "notifications and push-notification tokens;",
	"deleteAccount.s3ThirdParty": "linked third-party resources: a connected Strava authorisation is revoked, a RevenueCat subscriber record is deleted, and a connected Stripe payout account is unlinked and closed (Stripe retains transaction records under its own legal obligations).",
	"deleteAccount.s4Heading": "4. What is retained, and for how long",
	"deleteAccount.s4BackupsLabel": "Encrypted backups",
	"deleteAccount.s4BackupsPrefix": ": a deleted account may persist in point-in-time-recovery backups for up to ",
	"deleteAccount.s4BackupsWindow": "28 days",
	"deleteAccount.s4BackupsSuffix": " before they roll off. Backups are never used to restore a deleted account.",
	"deleteAccount.s4AuditLabel": "A minimal deletion audit record",
	"deleteAccount.s4AuditBody": ": a one-way hashed identifier and outcome counts, kept so we can prove the deletion happened. It cannot be used to identify you or recover any data.",
	"deleteAccount.s4PaymentsLabel": "Payment transaction records",
	"deleteAccount.s4PaymentsBody": ": retained by the payment processors (Stripe, the app stores) under their own legal obligations; we hold no card details ourselves.",
	"deleteAccount.s4MessagesLabel": "Messages other people sent you",
	"deleteAccount.s4MessagesBody": ": stay in the sender's conversation, with your account shown as deleted, until our two-year limit on direct messages removes them. The messages you sent are deleted with your account.",
	"deleteAccount.s4ReportsLabel": "Reported messages",
	"deleteAccount.s4ReportsBody": ": if someone reported a message you sent, a copy is kept with their report so moderators can review it, even after your account is deleted.",
	"deleteAccount.s4PolicyPrefix": "The full retention schedule for every data category is in the ",
	"deleteAccount.s4PolicySuffix": ".",
	"deleteAccount.s5Heading": "5. Deleting some data without closing the account",
	"deleteAccount.s5Intro": "To delete individual data without deleting the account:",
	"deleteAccount.s5ItemsLabel": "Runs, routes, photos, gym workouts, food-log entries, posts, comments",
	"deleteAccount.s5ItemsBody": ": open the item and use its Delete control. Runs can also be bulk-deleted from the Runs list via multi-select.",
	"deleteAccount.s5ServicesLabel": "Connected services",
	"deleteAccount.s5ServicesBody": " (Strava, parkrun, and similar): disconnect them in Settings → Integrations; disconnecting revokes our access.",
	"deleteAccount.s5OtherLabel": "Anything else, or if you prefer not to do it in the app",
	"deleteAccount.s5OtherPrefix": ": email ",
	"deleteAccount.s5OtherSuffix": " describing the data to delete, and we will action it with the same verification and timeline as section 2.",
	"deleteAccount.s5BackupsPrefix": "Deleted items leave encrypted backups within the same 28-day window described above. You can also ",
	"deleteAccount.s5ExportLink": "export your data",
	"deleteAccount.s5BackupsSuffix": " before deleting anything.",
	"deleteAccount.s6Heading": "6. Related documents",
	"deleteAccount.privacyPolicy": "Privacy Policy",
	"deleteAccount.terms": "Terms of Service",
	"deleteAccount.healthNotice": "Consumer Health Data Privacy Policy",
	"deleteAccount.cookieNotice": "Cookie Notice",
